/// <summary>
/// Active method trigger extension.
/// </summary>
/// <returns>Returns int as true/false.</returns>
public int active()
{
    int ret = next active();

    this.enableOrDisableMETSalesInvoiceGroup();

    return ret;
}

/// <summary>
/// Enable or Disable sales invoice report buttons based on condition
/// </summary>
public void enableOrDisableMETSalesInvoiceGroup()
{
    FormRun formRun = this.formRun();

    if (formRun != null && formRun.args().record() is SalesTable)
    {
        SalesTable salesTable = formRun.args().record();

        CustInvoiceJour custInvoiceJourLocal = CustInvoiceJour::findFromSalesId_IN(salesTable.SalesId);

        FormButtonGroupControl metBundleGroup = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, METPrintGroupBundle));
        FormButtonGroupControl metChargeThrough = formRun.design(1).controlName(formControlStr(CustInvoiceJournal, METPrintGroupChargeThrough));

        if (custInvoiceJourLocal && custInvoiceJourLocal.SalesId
            && (METSalesOrderTypes::find(salesTable.METSalesOrderType).SalesOrderTypeID == METConstants::SalesInvoiceChargeOnly
                || salesTable.checkForReturnCreditInvoice()))
        {                
            metBundleGroup.visible(true);
            metChargeThrough.visible(false);
        }
        else
        {

            metBundleGroup.visible(false);
            metChargeThrough.visible(true);
        }
    }
}
